examples.template:
MonarchAiWelcome(
    title = {{title}},
    agent = MonarchAiAgentRef(name = {{agent.name}}, role = {{agent.role}}),
    description = {{description}},
) {
    MonarchAiStarterPrompts(
        prompts = listOf(
            MonarchAiStarterPrompt({{prompts.0.id}}, {{prompts.0.title}}, {{prompts.0.prompt}}),
            MonarchAiStarterPrompt({{prompts.1.id}}, {{prompts.1.title}}, {{prompts.1.prompt}}),
        ),
        onSelect = { draft = it.prompt },
    )
}

examples.code:
MonarchAiWelcome(
    title = "How can I help?",
    agent = MonarchAiAgentRef(name = "Assistant", role = "Workspace assistant"),
    description = "I can read the page you are on and the documents you share with me.",
) {
    MonarchAiStarterPrompts(
        prompts = listOf(
            MonarchAiStarterPrompt("sum", "Summarise this page", "Summarise this page."),
            MonarchAiStarterPrompt("next", "Suggest next steps", "What should I do next on this project?"),
        ),
        onSelect = { draft = it.prompt },
    )
}
